//! Decisions from the pinned celestia-app memo helpers, generated by Go.
use x_packetforward::limits::{reject_forward_memo, retry_memo_within_limits};

#[test]
fn memo_decisions_match_go() {
    let fixtures: serde_json::Value = serde_json::from_str(include_str!(
        "../../../../../conformance/fixtures/pfm-limits.json"
    ))
    .unwrap();
    assert_eq!(
        fixtures["app_commit"],
        "9bb2bd1ac672cecaccd0b74bcefc79168f57158e"
    );
    let vectors = fixtures["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 70);
    for v in vectors {
        let name = v["name"].as_str().unwrap();
        let bytes = encoding::hex::decode(v["memo_hex"].as_str().unwrap()).unwrap();
        let memo = gostr::from_go_bytes(&bytes);
        assert_eq!(
            reject_forward_memo(&memo),
            v["reject_forward"].as_bool().unwrap(),
            "{name}: receive"
        );
        assert_eq!(
            retry_memo_within_limits(&memo),
            v["retry_within_limits"].as_bool().unwrap(),
            "{name}: retry"
        );
    }
}
